class MessageNotFoundError(Exception):
    """Throws when messages was not found."""


class VerificationError(Exception):
    """Throws when messages verification failed."""


class FoundError(Exception):
    """Throws when forbidden messages was found."""


class InspectionError(Exception):
    """Throws when inspector can't match given packet to if self."""


class MessageDefinitionError(Exception):
    """Throws when text definition of awaited messages can not be parsed."""
